using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

// ---------------------------------------------------------------------------
// Build host with DI
// ---------------------------------------------------------------------------
var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(b =>
    b.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18",
        new OpenAIClient(
            builder.Configuration["AI:ApiKey"]
                ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set AI:ApiKey in configuration or OPENAI_API_KEY env var."))));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<ResearchRunner>();

using var host = builder.Build();

var runner = host.Services.GetRequiredService<ResearchRunner>();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided — exiting.");
    return;
}

await runner.RunAsync(topic);

// ---------------------------------------------------------------------------
// Tools the agent can call
// ---------------------------------------------------------------------------
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public string SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results — replace with a real search API for production use.
        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") =>
                """
                1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
                2. Google achieved quantum supremacy in 2019 with their Sycamore processor (53 qubits).
                3. IBM launched the 1,121-qubit Condor processor in late 2023 and is targeting 100k qubits by 2033.
                4. Key applications include cryptography, drug discovery, materials science, and optimization.
                5. Major challenges: decoherence, error correction, and extreme cooling requirements (~15 millikelvins).
                """,
            var q when q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("machine learning") =>
                """
                1. AI systems now match or exceed human performance on many benchmarks (MMLU, HumanEval).
                2. Transformer architecture (2017) underpins modern LLMs like GPT-4, Claude, and Gemini.
                3. Generative AI market projected to reach $1.3 trillion by 2032 (Bloomberg Intelligence).
                4. Key concerns: alignment, bias, job displacement, energy consumption, and copyright.
                5. Agentic AI — models that plan, use tools, and act autonomously — is a fast-growing trend.
                """,
            var q when q.Contains("climate") || q.Contains("renewable energy") =>
                """
                1. Global temperatures have risen ~1.1°C above pre-industrial levels as of 2024.
                2. Renewable energy accounted for 30% of global electricity generation in 2023.
                3. Solar PV costs have dropped 90% since 2010, making it the cheapest energy source in many regions.
                4. The IEA projects renewables will supply 50% of global electricity by 2030.
                5. Carbon capture and green hydrogen are emerging technologies for hard-to-decarbonize sectors.
                """,
            _ =>
                $"""
                1. "{query}" is a topic of active research and discussion.
                2. Recent studies highlight significant advances and ongoing challenges in this field.
                3. Experts suggest interdisciplinary collaboration is key to further breakthroughs.
                4. Public interest and investment in this area have increased substantially in recent years.
                5. For the latest findings, consult peer-reviewed journals and authoritative databases.
                """
        };

        return results;
    }

    [Description("Save a research note. Use this to record key findings as you search.")]
    public string SaveNote(
        [Description("The text of the note to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join(Environment.NewLine,
            _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

// ---------------------------------------------------------------------------
// Agent runner
// ---------------------------------------------------------------------------
public sealed class ResearchRunner(IChatClient chatClient, ResearchTools tools, ILoggerFactory loggerFactory)
{
    public async Task RunAsync(string topic)
    {
        var aiTools = new List<AITool>
        {
            AIFunctionFactory.Create(tools.SearchWeb),
            AIFunctionFactory.Create(tools.SaveNote),
            AIFunctionFactory.Create(tools.GetNotes),
        };

        var agent = new ChatClientAgent(
            chatClient,
            instructions: """
                You are a research assistant. Your job is to thoroughly research a topic
                by searching the web, taking notes on key findings, and then producing a
                well-structured summary.

                Follow this workflow:
                1. Search the web with several relevant queries to gather broad information.
                2. Save important findings as notes using the SaveNote tool.
                3. Review your notes with GetNotes.
                4. Produce a final summary with sections: Overview, Key Findings, and Conclusion.
                """,
            name: "ResearchAgent",
            description: "An agent that researches topics using web search and note-taking tools",
            tools: aiTools,
            loggerFactory: loggerFactory);

        Console.WriteLine($"\n🔍 Researching: {topic}\n");

        var chatOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            },
            MaxIterations = 10,
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
        };

        var response = await agent.RunAsync(messages, options: chatOptions);

        Console.WriteLine("── Research Complete ──────────────────────────────────\n");
        Console.WriteLine(response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant)?.Text
            ?? "No response generated.");
        Console.WriteLine("\n──────────────────────────────────────────────────────");

        // Show collected notes
        Console.WriteLine("\n📝 Raw Notes:");
        Console.WriteLine(tools.GetNotes());
    }
}

